129→describe("BIP-32/BIP-44 y direcciones Ethereum", () => {
130→  const seed = deriveBip39Seed(MNEMONIC_HARDHAT);

  it("reproduce los cuatro vectores Hardhat/Anvil", () => {
    const expected = [
      "0xf39Fd6e51aad88F6F4ce6aB8827279cffFb92266",
      "0x70997970C51812dc3A010C7d01b50e0d17dc79C8",
      "0x3C44CdDdB6a900fa2b585dd299e03d12FA4293BC",
      "0x90F79bf6EB2c4f870365E785982E1f101E93b906",
    ];
    assert.deepEqual(expected.map((_, index) => deriveEthereumAddress(seed, index)), expected);
140→  });

  it("construye el path hardened exacto y no expone clave privada", () => {
    assert.equal(ethereumDerivationPath(7), "m/44'/60'/0'/0/7");
    const derived = deriveEthereumKey(seed, 7);
    assert.deepEqual(Object.keys(derived).sort(), ["address", "addressIndex", "derivationPath", "publicKey"]);
    assert.match(derived.publicKey, /^0x[0-9a-fA-F]{66}$/);
  });

  it("reproduce los vectores canónicos EIP-55 carácter por carácter", () => {
150→    const vectors = [
      ["5aaeb6053f3e94c9b9a09f33669435e7ef1beaed", "0x5aAeb6053F3E94C9b9A09f33669435E7Ef1BeAed"],
      ["fb6916095ca1df60bb79ce92ce3ea74c37c5d359", "0xfB6916095ca1df60bB79Ce92cE3Ea74c37c5d359"],
      ["dbf03b407c01e7cd3cbea99509d93f8dddc8c6fb", "0xdbF03B407c01E7cD3CBea99509d93f8DDDC8C6FB"],
      ["d1220a0cf47c7b9be7a2e6ba89f429762e7b9adb", "0xD1220A0cf47c7B9Be7A2E6BA89F429762e7b9aDb"],
    ] as const;
    for (const [raw, expected] of vectors) assert.equal(toChecksumAddress(raw), expected);
  });

  it("acepta el último índice normal y rechaza índices hardened o no enteros", () => {
160→    assert.equal(validateAddressIndex(MAX_ADDRESS_INDEX), MAX_ADDRESS_INDEX);
    assert.equal(ethereumDerivationPath(MAX_ADDRESS_INDEX), `m/44'/60'/0'/0/${MAX_ADDRESS_INDEX}`);
    assert.match(deriveEthereumAddress(seed, MAX_ADDRESS_INDEX), /^0x[0-9a-fA-F]{40}$/);
    for (const invalid of [-1, 1.5, MAX_ADDRESS_INDEX + 1]) {
      assert.throws(
        () => validateAddressIndex(invalid),
        (error: unknown) => error instanceof WalletCryptoError &&
          error.code === "VALIDATION_ERROR" && error.issues?.[0]?.field === "address_index",
