    { name: "account", initialIndex: 0x80000000, expectedPath: "m/44'/60'/1'/0/7", expectedAddressIndex: 7 },
    { name: "change", initialIndex: 0, expectedPath: "m/44'/60'/0'/1/7", expectedAddressIndex: 7 },
    { name: "address index", initialIndex: 7, expectedPath: "m/44'/60'/0'/0/8", expectedAddressIndex: 8 },
  ] as const;

180→  const invalidConditions = ["I_L >= n", "k_hijo == 0"] as const;

  for (const [targetLevel, level] of derivationLevels.entries()) {
    for (const condition of invalidConditions) {
      it(`reintenta ${level.name} en el mismo nivel ante ${condition}`, () => {
