        assert.deepEqual(firstInjection.targetKeys[0], firstInjection.targetKeys[1]);
        assert.deepEqual(firstInjection.targetDataPrefixes[0], firstInjection.targetDataPrefixes[1]);

        // The same injected invalid child must select the same effective path and key.
        const secondInjection = invalidChildHmac(targetLevel, condition);
        assert.deepEqual(deriveEthereumKey(seed, 7, secondInjection.hmac), result);
      });
    }
200→  }
});

const SECP256K1_ORDER = BigInt(
  "0xFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFEBAAEDCE6AF48A03BBFD25E8CD0364141",
);

function invalidChildHmac(
  targetLevel: number,
  condition: "I_L >= n" | "k_hijo == 0",
210→): {
  hmac: (key: Uint8Array, data: Uint8Array) => Uint8Array;
  attemptedIndices: number[];
  targetKeys: Buffer[];
  targetDataPrefixes: Buffer[];
} {
  let parentPrivateKey: bigint | undefined;
  let successfulLevel = 0;
  let injected = false;
  const attemptedIndices: number[] = [];
220→  const targetKeys: Buffer[] = [];
  const targetDataPrefixes: Buffer[] = [];

  return {
    attemptedIndices,
    targetKeys,
    targetDataPrefixes,
    hmac(key, data) {
      const actual = createHmac("sha512", key).update(data).digest();
      if (parentPrivateKey === undefined) {
230→        parentPrivateKey = bytesToTestBigInt(actual.subarray(0, 32));
        return actual;
      }

      if (successfulLevel === targetLevel) {
        const serialized = Buffer.from(data);
        attemptedIndices.push(serialized.readUInt32BE(serialized.length - 4));
        targetKeys.push(Buffer.from(key));
        targetDataPrefixes.push(serialized.subarray(0, serialized.length - 4));
        if (!injected) {
240→          injected = true;
          const invalidLeft = condition === "I_L >= n"
            ? SECP256K1_ORDER
            : SECP256K1_ORDER - parentPrivateKey;
          return Buffer.concat([testBigIntTo32Bytes(invalidLeft), actual.subarray(32)]);
        }
      }

      const left = bytesToTestBigInt(actual.subarray(0, 32));
      parentPrivateKey = (parentPrivateKey + left) % SECP256K1_ORDER;
250→      successfulLevel += 1;
      return actual;
    },
  };
}

function bytesToTestBigInt(value: Uint8Array): bigint {
  return BigInt(`0x${Buffer.from(value).toString("hex")}`);
}

