from pathlib import Path
text = Path("candidatos.txt").read_text()
blocks = []
cur = None
for line in text.splitlines():
    if line.startswith("K-"):
        if cur:
            blocks.append(cur)
        parts = line.split(maxsplit=1)
        kid = parts[0]
        loc = parts[1] if len(parts)>1 else ""
        cur = {"id": kid, "loc": loc, "lines": [line]}
    elif cur is not None:
        cur["lines"].append(line)
if cur:
    blocks.append(cur)
print("count", len(blocks))
print("first", blocks[0]["id"], blocks[0]["loc"])
print("last", blocks[-1]["id"], blocks[-1]["loc"])
# extract cita (line with >)
missing = []
for b in blocks:
    cita = None
    for ln in b["lines"]:
        if ">" in ln[0:20] or (len(ln)>6 and ln.lstrip()[0:1]!="" and ">" in ln):
            pass
    # typical: '   197> text' or '      7> text'
    for ln in b["lines"][1:]:
        if ">" in ln:
            # find first '>' that looks like marker
            import re
            m = re.match(r"\s*\d+>\s?(.*)$", ln)
            if m:
                cita = m.group(1)
                break
    if not cita:
        missing.append(b["id"])
        cita = ""
    b["cita"] = cita
print("missing cita", missing[:20], "n", len(missing))
# print a few citas
for b in blocks:
    if b["id"] in ("K-001","K-021","K-043","K-070","K-141","K-248","K-260"):
        print(b["id"], "|", b["loc"], "|", b["cita"][:180])
