rawOutput.command:
python3 - <<'PY'
from pathlib import Path
import re
text = Path("candidatos.txt").read_text()
blocks = []
cur = None
for line in text.splitlines():
    if line.startswith("K-"):
        if cur: blocks.append(cur)
        parts = line.split(maxsplit=1)
        cur = {"id": parts[0], "loc": parts[1], "lines": []}
    elif cur is not None:
        cur["lines"].append(line)
if cur: blocks.append(cur)
for b in blocks:
    cita = None
    for ln in b["lines"]:
        m = re.match(r"\s*\d+>\s?(.*)$", ln)
        if m:
            cita = m.group(1)
            break
    print(f"{b['id']}\t{b['loc']}\t{cita[:120]}")
PY

