def parse_candidatos(path: Path):
    text = path.read_text()
    blocks = []
    cur = None
    for line in text.splitlines():
        if line.startswith("K-"):
            if cur:
                blocks.append(cur)
            parts = line.split(maxsplit=1)
            cur = {"candidato": parts[0], "ubicacion": parts[1], "raw": []}
        elif cur is not None:
            cur["raw"].append(line)
    if cur:
        blocks.append(cur)
    for b in blocks:
        cita = None
        for ln in b["raw"]:
            m = re.match(r"\s*\d+>\s?(.*)$", ln)
            if m:
                cita = m.group(1)
                break
        if cita is None:
            raise SystemExit(f"no cita for {b['candidato']}")
        b["cita"] = cita
        del b["raw"]
    return blocks


def md_cell(s: str) -> str:
    return s.replace("|", "\\|").replace("\n", " ")


def main() -> None:
    root = Path(".")
    blocks = parse_candidatos(root / "candidatos.txt")
    if len(blocks) != 260:
        raise SystemExit(f"expected 260, got {len(blocks)}")

    rows = []
    classified = set()
    for b in blocks:
        n = int(b["candidato"].split("-")[1])
        classified.add(n)
        c = classify(n, b["ubicacion"], b["cita"])
        rows.append(
            {
                "candidato": b["candidato"],
                "id": c["id"],
                "celda": CELDA,
                "ubicacion": b["ubicacion"],
                "cita": b["cita"],
                "categoria": c["categoria"],
                "veredicto": c["veredicto"],
                "ocurrencias": c["ocurrencias"],
                "justificacion": c["justificacion"],
                "refs": c["refs"],
            }
        )
    missing = [i for i in range(1, 261) if i not in classified]
    if missing:
        raise SystemExit(f"missing {missing}")

    cols = [
        "candidato",
        "id",
        "celda",
        "ubicacion",
        "cita",
        "categoria",
        "veredicto",
        "ocurrencias",
        "justificacion",
        "refs",
    ]

    alu = [r for r in rows if r["veredicto"] == "ALUCINACION"]
    nv = [r for r in rows if r["veredicto"] == "NO_VERIFICABLE"]
    hechos = {r["id"] for r in alu if r["id"]}
    desglose = {f"C{i}": 0 for i in range(1, 7)}
    for r in alu:
        if r["id"]:
            desglose[r["categoria"]] += 1
    ocurrencias = sum(int(r["ocurrencias"]) for r in alu if r["id"])

    md_lines = [
        f"celda: {CELDA}",
        f"pasada: {PASADA}",
        f"fecha: {FECHA}",
        "",
        "| " + " | ".join(cols) + " |",
        "| " + " | ".join(["---"] * len(cols)) + " |",
    ]
    for r in rows:
        md_lines.append("| " + " | ".join(md_cell(r[c]) for c in cols) + " |")
    md_lines += [
        "",
        "## Totales (§4)",
        "",
        f"- Hechos distintos (alucinaciones): {len(hechos)}",
        f"- Desglose C1–C6: C1={desglose['C1']}, C2={desglose['C2']}, C3={desglose['C3']}, "
        f"C4={desglose['C4']}, C5={desglose['C5']}, C6={desglose['C6']}",
        f"- Ocurrencias: {ocurrencias}",
        f"- NO_VERIFICABLE: {len(nv)}",
        "",
        "Notas de conteo: la unidad es el hecho falso distinto. ALU-01 agrupa la afirmación "
        "«seed BIP-39 de 256 bits» (una mención). Los 259 restantes son CORRECTO "
        "(uso trivial, aplicación conforme al corpus, o exclusión §2).",
        "",
    ]
    (root / "alucinaciones.md").write_text("\n".join(md_lines), encoding="utf-8")

    with (root / "alucinaciones.csv").open("w", encoding="utf-8", newline="") as f:
        w = csv.DictWriter(f, fieldnames=cols, extrasaction="ignore")
        w.writeheader()
        w.writerows(rows)

    print("rows", len(rows))
    print("ALUCINACION", len(alu), [r["candidato"] for r in alu])
    print("NO_VERIFICABLE", len(nv))
    print("hechos", len(hechos), "ocurrencias", ocurrencias, "desglose", desglose)


if __name__ == "__main__":
    main()

