    bip32_review = {6}
    secp = {9, 104, 242, 243, 244}
    keccak = {97, 145}
    compressed = {103}
    eth_field = {70, 77, 78, 187, 188, 189}
    chain_err = {82, 83, 197}
    deriv_triv = {79, 102, 146, 162, 165, 173, 176, 178, 181, 182, 183, 184, 185, 230}
    hardened = {101, 106}
