    eip681 = {8, 24, 50, 254, 255, 256, 257, 258, 259}
    bip39_24 = {4, 16, 91, 115, 116, 117, 118, 119, 120, 126, 127, 128, 211, 212, 213, 214, 215}
    # 91 is rpc invalid response - wait don't put 91 in bip39
