    bip44_path = {25, 131, 132, 138, 139, 140, 152, 153, 154, 201, 226, 228, 229, 233, 234}
    bip32_review = {6}
    secp = {9, 104, 242, 243, 244}
    keccak = {97, 145}
    compressed = {103}
    eth_field = {70, 77, 78, 187, 188, 189}
    chain_err = {82, 83, 197}
    deriv_triv = {79, 102, 146, 162, 165, 173, 176, 178, 181, 182, 183, 184, 185, 230}
    hardened = {101, 106}
    skip_levels = {235, 236, 237, 238, 239, 240, 241}
    checksum_re = {43, 44, 47}
    wl_reject = {220}
    hardhat = {206}
    ckd_formula = {150, 245}
    trivial_chain = set()  # covered in sepolia
    # leftovers handled below

    refs = ""
    if n in {28, 50}:
        refs = "AT-11-06-01"
    elif n in {32, 34, 53, 54}:
        refs = "AT-11-06-26"

    if n in eip55:
        j = J_EIP55
    elif n in getcode:
        j = J_GETCODE
    elif n in jsonrpc:
        j = J_JSONRPC
    elif n in chainid_rpc:
        j = J_CHAINID_RPC
    elif n in sepolia:
        j = J_SEPOLIA
    elif n in eip681_eth:
        j = J_EIP681_ETH
    elif n in eip681_usdc:
        j = J_EIP681_USDC
    elif n in eip681:
        j = J_EIP681
    elif n in bip39_24:
        j = J_BIP39_24
    elif n in bip39_seed:
        j = J_BIP39_SEED512
    elif n in bip39_nfkd:
        j = J_BIP39_NFKD
    elif n in bip39_wl:
        j = J_BIP39_WL
    elif n in bip39_cs:
        j = J_BIP39_CHECKSUM
    elif n in bip39_kat:
        j = J_BIP39_KAT
    elif n in bip39_triv:
        j = J_BIP39_TRIVIAL
    elif n in passphrase:
        j = J_PASSPHRASE
    elif n in bip32_ckd:
        j = J_BIP32_CKD
    elif n in bip32_master:
        j = J_BIP32_MASTER
    elif n in bip32_skip:
        j = J_BIP32_SKIP if n not in {248, 251} else J_TRACE_BIP32
    elif n in bip44_path:
        j = J_BIP44_PATH
    elif n in bip32_review:
        j = J_BIP32_REVIEW
    elif n in secp:
        j = J_SECP
    elif n in keccak:
        j = J_KECCAK_ADDR if n == 145 else (
            "CORRECTO: Keccak-256 es la función de hash de EIP-55 y de la dirección Ethereum "
            "(corpus/documentos/erc-55.md; spec HU-06-02 RN-4), no SHA-256."
        )
    elif n in compressed:
        j = J_COMPRESSED
    elif n in eth_field:
        j = J_ETH_FIELD
    elif n in chain_err:
        j = J_CHAIN_ERR
    elif n in deriv_triv:
        j = J_DERIV_TRIVIAL
    elif n in hardened:
        j = J_HARDENED_RANGE
    elif n in skip_levels:
        j = J_SKIP_LEVELS
    elif n in checksum_re:
        j = J_CHECKSUM_REGEX
    elif n in wl_reject:
        j = J_WORDLIST_REJECT
    elif n in hardhat:
        j = J_HARDHAT
    elif n in ckd_formula:
        j = J_CKD_FORMULA
    else:
        raise SystemExit(f"unclassified K-{n:03d} {loc} {cita[:80]}")

    return {
        "id": "",
        "categoria": "",
        "veredicto": "CORRECTO",
        "ocurrencias": "1",
        "justificacion": j,
        "refs": refs,
    }


def parse_candidatos(path: Path):
    text = path.read_text()
    blocks = []
    cur = None
    for line in text.splitlines():
        if line.startswith("K-"):
            if cur:
                blocks.append(cur)
            parts = line.split(maxsplit=1)
            cur = {"candidato": parts[0], "ubicacion": parts[1], "raw": []}
        elif cur is not None:
            cur["raw"].append(line)
    if cur:
        blocks.append(cur)
    for b in blocks:
        cita = None
        for ln in b["raw"]:
            m = re.match(r"\s*\d+>\s?(.*)$", ln)
            if m:
                cita = m.group(1)
                break
        if cita is None:
            raise SystemExit(f"no cita for {b['candidato']}")
        b["cita"] = cita
        del b["raw"]
    return blocks


def md_cell(s: str) -> str:
    return s.replace("|", "\\|").replace("\n", " ")


def main() -> None:
    root = Path(".")
    blocks = parse_candidatos(root / "candidatos.txt")
    if len(blocks) != 260:
        raise SystemExit(f"expected 260, got {len(blocks)}")

    rows = []
    classified = set()
    for b in blocks:
        n = int(b["candidato"].split("-")[1])
        classified.add(n)
        c = classify(n, b["ubicacion"], b["cita"])
        rows.append(
            {
                "candidato": b["candidato"],
                "id": c["id"],
                "celda": CELDA,
                "ubicacion": b["ubicacion"],
                "cita": b["cita"],
                "categoria": c["categoria"],
                "veredicto": c["veredicto"],
                "ocurrencias": c["ocurrencias"],
                "justificacion": c["justificacion"],
                "refs": c["refs"],
            }
        )
    missing = [i for i in range(1, 261) if i not in classified]
    if missing:
        raise SystemExit(f"missing {missing}")

    cols = [
        "candidato",
        "id",
        "celda",
        "ubicacion",
        "cita",
        "categoria",
        "veredicto",
        "ocurrencias",
        "justificacion",
        "refs",
    ]

    alu = [r for r in rows if r["veredicto"] == "ALUCINACION"]
    nv = [r for r in rows if r["veredicto"] == "NO_VERIFICABLE"]
    hechos = {r["id"] for r in alu if r["id"]}
    desglose = {f"C{i}": 0 for i in range(1, 7)}
    for r in alu:
        if r["id"]:
            desglose[r["categoria"]] += 1
    ocurrencias = sum(int(r["ocurrencias"]) for r in alu if r["id"])

    md_lines = [
        f"celda: {CELDA}",
        f"pasada: {PASADA}",
        f"fecha: {FECHA}",
        "",
        "| " + " | ".join(cols) + " |",
        "| " + " | ".join(["---"] * len(cols)) + " |",
    ]
    for r in rows:
        md_lines.append("| " + " | ".join(md_cell(r[c]) for c in cols) + " |")
    md_lines += [
        "",
        "## Totales (§4)",
        "",
        f"- Hechos distintos (alucinaciones): {len(hechos)}",
        f"- Desglose C1–C6: C1={desglose['C1']}, C2={desglose['C2']}, C3={desglose['C3']}, "
        f"C4={desglose['C4']}, C5={desglose['C5']}, C6={desglose['C6']}",
        f"- Ocurrencias: {ocurrencias}",
        f"- NO_VERIFICABLE: {len(nv)}",
        "",
        "Notas de conteo: la unidad es el hecho falso distinto. ALU-01 agrupa la afirmación "
        "«seed BIP-39 de 256 bits» (una mención). Los 259 restantes son CORRECTO "
        "(uso trivial, aplicación conforme al corpus, o exclusión §2).",
        "",
    ]
    (root / "alucinaciones.md").write_text("\n".join(md_lines), encoding="utf-8")

    with (root / "alucinaciones.csv").open("w", encoding="utf-8", newline="") as f:
        w = csv.DictWriter(f, fieldnames=cols, extrasaction="ignore")
        w.writeheader()
        w.writerows(rows)

    print("rows", len(rows))
    print("ALUCINACION", len(alu), [r["candidato"] for r in alu])
    print("NO_VERIFICABLE", len(nv))
    print("hechos", len(hechos), "ocurrencias", ocurrencias, "desglose", desglose)


if __name__ == "__main__":
    main()
